package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.time.Instant;
import java.util.*;
/** Native portal support eligibility and admission-time case units. */
final class CustomerEntitlements {
 private CustomerEntitlements() {}
 static Map<String,Object> display(Store.Db db,Map<String,Object> row)throws SQLException{row.put("start",Instant.ofEpochMilli(((Number)row.get("starts")).longValue()).toString());row.put("end",Instant.ofEpochMilli(((Number)row.get("ends")).longValue()).toString());long used=db.count("SELECT COUNT(*) FROM os_customer_case WHERE entitlement_id=?",row.get("entitlement_id"));row.put("used",used);row.put("remaining",Math.max(0,((Number)row.get("case_limit")).longValue()-used));return row;}
 static List<Map<String,Object>> list(Store.Db db,String account)throws SQLException{var rows=db.all("SELECT * FROM os_customer_entitlement WHERE account_id=? ORDER BY name,entitlement_id",account);for(var row:rows)display(db,row);return rows;}
 static Map<String,Object> find(Store.Db db,String account,String id)throws SQLException{var row=db.one("SELECT * FROM os_customer_entitlement WHERE account_id=? AND entitlement_id=?",account,id);if(row==null)throw new Failure(404,"Support entitlement not found");return row;}
 static void save(Store.Db db,String account,Object input)throws SQLException{
  Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);require(body.keySet().equals(Set.of("entitlement_id","name","description","active","start","end","case_limit","revision")),"Provide the reviewed entitlement fields");require(body.get("entitlement_id") instanceof String,"Provide an entitlement identifier or empty text for new");String id=body.get("entitlement_id").toString();var current=id.isEmpty()?map("revision",0):find(db,account,id);ProblemInvestigations.revision(body.get("revision"),current.get("revision"));String name=WorkJobs.text(body.get("name"),160),description=WorkJobs.text(body.get("description"),4000);require(body.get("active") instanceof Boolean,"Choose active or inactive");require(body.get("case_limit") instanceof Integer n && n>=0 && n<=100000,"Use a case limit from 0 to 100000; 0 means unlimited");long start=ChangeScheduling.instant(body.get("start")),end=ChangeScheduling.instant(body.get("end"));require(end>start,"Entitlement end must follow its start");
  if(id.isEmpty()){require(db.count("SELECT COUNT(*) FROM os_customer_entitlement WHERE account_id=?",account)<20,"At most 20 entitlements belong to an account");id=Values.id();}db.update("INSERT INTO os_customer_entitlement(entitlement_id,account_id,name,description,active,starts,ends,case_limit,revision) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(entitlement_id) DO UPDATE SET name=excluded.name,description=excluded.description,active=excluded.active,starts=excluded.starts,ends=excluded.ends,case_limit=excluded.case_limit,revision=excluded.revision",id,account,name,description,(Boolean)body.get("active")?1:0,start,end,body.get("case_limit"),((Number)current.get("revision")).intValue()+1);SecurityEvents.record(db,db.viewerId,db.viewerId,"customer.entitlement_saved",map("account_id",account,"entitlement_id",id));
 }
 static Map<String,Object> eligible(Store.Db db,String id,long now)throws SQLException{
  if(!"requester".equals(db.viewerRole))throw new Failure(403,"Customer requester access required");var row=db.one("SELECT e.* FROM os_customer_entitlement e JOIN os_customer_account a ON a.account_id=e.account_id JOIN os_customer_contact c ON c.account_id=a.account_id JOIN os_user u ON u.user_id=c.user_id WHERE e.entitlement_id=? AND c.user_id=? AND c.active=1 AND a.active=1 AND u.active=1 AND u.role='requester' AND u.password_reset_required=0 AND e.active=1 AND e.starts<=? AND e.ends>? AND EXISTS(SELECT 1 FROM os_record g WHERE g.sys_id=a.group_id AND g.\"table\"='sys_user_group') AND (e.case_limit=0 OR (SELECT COUNT(*) FROM os_customer_case x WHERE x.entitlement_id=e.entitlement_id)<e.case_limit)",id,db.viewerId,now,now);if(row==null)throw new Failure(404,"No current support entitlement for this request");RecordPolicy.read(db,Service.schema(db,"customer_case"));RecordPolicy.require(Service.schema(db,"customer_case"),"create",db.viewerRole);if(!FieldAccess.allowed(db,Service.schema(db,"customer_case"),"description"))throw new Failure(403,"Case description access required");return display(db,row);
 }
}
